import{z as l,x as B,o as e,c as S,q as t,j as o,D as E,d as r,s as A,S as n,b as s}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"CORS","description":"","frontmatter":{"title":"CORS","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cors.md","filePath":"cs/cors.md","lastUpdated":1791413859000}'),C={name:"cs/cors.md"};function d(c,a,p,O,D,h){const i=B("Mermaid");return e(),S("div",null,[a[2]||(a[2]=t('<h1 id="cors" tabindex="-1">CORS <a class="header-anchor" href="#cors" aria-label="Permalink to &quot;CORS&quot;">​</a></h1><div class="epigraph"><p>同源政策默认不让外源脚本读你的响应。CORS 是服务器显式放行的口子：哪个 Origin、是否带凭证。放行过宽等于把 SOP 拆掉。</p><footer>—— W3C CORS；Fetch 标准；对照[同源](/cs/same-origin-csrf)</footer></div><p>上一课<a href="/cs/csp">CSP</a>限制本页能连什么；缺口是反方向——<strong>别人的页面想读你的 API</strong>。同源政策默认不许，CORS 是服务器显式放行的口子：预检请求与 Access-Control 响应头。不给窃取数据的操作步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>SOP 默认挡住跨源读，这是机密性的浏览器侧防线。API 要服务合法前端就得放行，但放行写错就成了洞：把请求的 Origin 头原样反射、再加允许凭证，等于任何网站的脚本都能带着用户 Cookie 读你的 API 响应。缺口是白名单精确匹配——完整 Origin 字符串比对，不做子串或前缀匹配。</p><h3 id="cors-不是-csrf-解" tabindex="-1">CORS 不是 CSRF 解 <a class="header-anchor" href="#cors-不是-csrf-解" aria-label="Permalink to &quot;CORS 不是 CSRF 解&quot;">​</a></h3><p>CORS 不是 CSRF 的解：表单、图片标签触发的简单请求本来就允许跨源发出（只是读不到响应），CORS 管不了「请求被发出」本身。CSRF 仍要 SameSite 或令牌。</p><p><span class="marginnote">Fetch 标准。本课禁止利用错误 CORS 的配方，只要求永不反射不可信 Origin。</span></p><p><span class="marginnote">同源政策可以想象成小区门禁：别处网页可以让请求「送进」你的服务器，但不许顺路拆看回信（读响应）。CORS 就是服务器自己贴出的授权名单，写明哪些外来者有权拆信——名单抄得太松，门禁就形同虚设。</span></p><p><span class="marginnote">常见误区：以为「CORS 报错＝请求被挡住了」。实际上大多数被拒的跨源请求已经发出、服务器也已经处理，浏览器只是拒绝把响应交给脚本。所以 CORS 不是防火墙，管不住「请求发生」，这才需要 SameSite 与令牌。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法先把请求分两类：简单请求直接发出，浏览器看响应头决定是否把响应体交给脚本；非简单请求先发 OPTIONS 预检，服务器放行才发正式请求。凭证模式下 allow-origin 不得用通配符——标准与常识在此一致。对照下一课点击劫持：那是 UI 层的欺骗，与读响应无关。</p>',13)),(e(),o(n,null,{default:E(()=>[A(i,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20ORIGIN%5B%22%E8%AF%B7%E6%B1%82%20Origin%22%5D%20--%3E%20ACL%5B%22%E6%98%AF%E5%90%A6%E5%9C%A8%E7%99%BD%E5%90%8D%E5%8D%95%22%5D%0A%20%20ACL%20--%3E%20READ%5B%22%E5%B8%A6%E5%87%AD%E8%AF%81%E8%AF%BB%E5%93%8D%E5%BA%94%22%5D%0A%20%20ACL%20--%3E%20DENY%5B%22%E6%B5%8F%E8%A7%88%E5%99%A8%E4%B8%8D%E6%8A%8A%E4%BD%93%E4%BA%A4%E7%BB%99%E5%A4%96%E6%BA%90%E8%84%9A%E6%9C%AC%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s("h2",{id:"机制",tabindex:"-1"},[r("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=s("p",null,"机制定位在 CIA 的 C：跨源读是机密性事件。配置正确时 SOP 仍挡住所有未列名来源；过宽的 CORS 把「只有自家前端能读」改成「任何网站都能以用户身份读」，等于在这个 API 上把 SOP 拆掉——而且这是服务器配置错误，浏览器侧无法补救。点击劫持下一课是用户在看不见的框里点。",-1)),(e(),o(n,null,{default:E(()=>[A(i,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E8%84%9A%E6%9C%AC%E8%A6%81%E5%8F%91%E8%B7%A8%E6%BA%90%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20S%7B%22%E5%B1%9E%E4%BA%8E%E7%AE%80%E5%8D%95%E8%AF%B7%E6%B1%82%3F%22%7D%0A%20%20S%20--%20%22%E6%98%AF%22%20--%3E%20SEND%5B%22%E7%9B%B4%E6%8E%A5%E5%8F%91%E5%87%BA%20%E6%AD%A3%E5%BC%8F%E8%AF%B7%E6%B1%82%22%5D%0A%20%20S%20--%20%22%E5%90%A6%22%20--%3E%20PRE%5B%22%E5%85%88%E5%8F%91%20OPTIONS%20%E9%A2%84%E6%A3%80%E6%89%93%E6%8B%9B%E5%91%BC%22%5D%0A%20%20PRE%20--%20%22%E6%94%BE%E8%A1%8C%E5%A4%B4%E5%8C%B9%E9%85%8D%22%20--%3E%20SEND%0A%20%20PRE%20--%20%22%E4%B8%8D%E6%94%BE%E8%A1%8C%22%20--%3E%20STOP%5B%22%E6%AD%A3%E5%BC%8F%E8%AF%B7%E6%B1%82%E4%B8%8D%E5%8F%91%E5%87%BA%22%5D%0A%20%20SEND%20--%3E%20RD%5B%22%E6%B5%8F%E8%A7%88%E5%99%A8%E5%86%B3%E5%AE%9A%E6%98%AF%E5%90%A6%E6%8A%8A%E5%93%8D%E5%BA%94%E4%BD%93%E4%BA%A4%E7%BB%99%E8%84%9A%E6%9C%AC%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p><span class="marginnote">预检（OPTIONS）可以翻译成「先打招呼」：要发带自定义头或 PUT/DELETE 这类不寻常的请求时，浏览器先发一个不带业务数据的 OPTIONS 问服务器「等下这种请求你收吗」，拿到匹配的放行头才发正式请求——简单请求则省掉这一步。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写 PoC 页；边界要点名：Origin 头可被非浏览器客户端伪造，CORS 因此从不充当鉴权，只是读权限的补充闸门。点击劫持下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CSP 管本页；CORS 管谁能读本 API。</li><li>反射 Origin 加凭证是拆 SOP。</li><li>CORS 不替代 CSRF 防御。</li><li>下一课点击劫持。</li><li>出处：W3C CORS / Fetch；<a href="/cs/same-origin-csrf">same-origin-csrf</a>。</li></ul>',5))])}const R=l(C,[["render",d]]);export{P as __pageData,R as default};
